-- Dominio: Contenido y preguntas
-- Banco de preguntas de selección múltiple para Lengua y Literatura,
-- Currículum Regular, 1° Medio (D.S. 614/2013), 4 ejes: Lectura, Escritura,
-- Comunicación Oral, Investigación. 4 preguntas por cada uno de los 17
-- objetivos de aprendizaje ya cargados en
-- supabase/seed/0015_curriculum_lenguaje_regular_7basico_2medio.sql
-- (unit_id + level_id + short_name, NUNCA ids hardcodeados).
--
-- Mismo criterio editorial, de validación, de formato y de idempotencia
-- documentado en supabase/seed/0064_question_bank_lenguaje_regular_
-- 7basico.sql -- no se repite aquí el detalle completo. Resumen:
--   - `review_status = 'borrador'`, `validation_status =
--     'ai_generated_review_required'`, `is_active = true`,
--     `source_type = 'validapp_original'`, `framework_id` NULL.
--   - NINGUNA pregunta de este archivo se muestra a estudiantes hasta
--     revisión y aprobación humana individual (ver 0023, 0064 y
--     `lib/data/essays.ts`).
--   - Fragmentos citados dentro de los enunciados son creaciones originales
--     de ValidApp con fines pedagógicos, no citas de obras reales.
--   - `content_hash` queda NULL (se calcula en TypeScript, no en SQL); este
--     archivo se validó localmente con el mismo script Node ad-hoc que
--     replica `validateQuestion`/`computeContentHash`/`textSimilarity`.
--   - Idempotencia con `where not exists (...)` sobre
--     `learning_objective_id` + `prompt`. Seed SOLO local.

-- ============================================================================
-- EJE: LECTURA — 1° MEDIO (5 objetivos x 4 preguntas = 20)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Estructura y visión de mundo de obras completas', 'Al analizar la estructura de una novela completa, ¿qué elemento corresponde a la "visión de mundo" que transmite la obra?', '["El número de capítulos que tiene la novela","El conjunto de valores, ideas e interpretación de la realidad que refleja la obra","El tamaño de la portada de la edición","El género editorial en que fue publicada"]', 1, 'La visión de mundo corresponde al conjunto de valores e interpretación de la realidad que transmite una obra, más allá de aspectos formales o editoriales.', 'inicial', 60),
  ('Estructura y visión de mundo de obras completas', 'Una obra dramática presenta un final trágico donde el destino resulta inevitable para los personajes. ¿Qué visión de mundo podría reflejar esta estructura?', '["Una visión optimista donde todo se resuelve favorablemente","Una visión donde el destino o las fuerzas externas determinan el curso de los hechos","Una visión que no tiene relación con la vida humana","Una visión cómica y despreocupada de la existencia"]', 1, 'Un final trágico e inevitable suele reflejar una visión de mundo donde el destino o fuerzas externas determinan los hechos, por encima de la voluntad de los personajes.', 'intermedia', 90),
  ('Estructura y visión de mundo de obras completas', '¿Cuál de las siguientes NO es una pregunta útil para analizar la visión de mundo de una obra completa?', '["¿Qué valores se privilegian o critican en la obra?","¿Cómo se resuelve el conflicto principal y qué dice eso sobre la existencia humana?","¿Cuántas páginas tiene la edición que se está leyendo?","¿Qué rol cumplen el destino, la libertad o la sociedad en la obra?"]', 2, 'La cantidad de páginas de una edición es un dato material que no aporta a la interpretación de la visión de mundo de la obra.', 'intermedia', 90),
  ('Estructura y visión de mundo de obras completas', 'En una novela, la estructura fragmentada en múltiples voces narrativas refleja la imposibilidad de una única verdad sobre los hechos. ¿Qué relación existe entre la estructura y la visión de mundo de la obra?', '["Ninguna, la estructura no tiene relación con el sentido de la obra","La estructura fragmentada refuerza formalmente una visión de mundo relativista o plural","La estructura solo busca confundir al lector sin ningún propósito","Toda novela con varias voces narrativas tiene el mismo significado"]', 1, 'La forma narrativa (estructura fragmentada) puede reforzar y expresar formalmente una visión de mundo, en este caso una donde no existe una única verdad.', 'avanzada', 120),

  ('Comprensión de ensayos y textos argumentativos complejos', '¿Qué caracteriza a un ensayo como texto argumentativo?', '["Presenta una reflexión personal fundamentada sobre un tema, con una tesis y argumentos","Es un texto narrativo con personajes ficticios","Solo contiene datos estadísticos sin ninguna interpretación","No puede incluir la opinión del autor"]', 0, 'Un ensayo se caracteriza por presentar una reflexión personal fundamentada sobre un tema, organizada en torno a una tesis y argumentos.', 'inicial', 60),
  ('Comprensión de ensayos y textos argumentativos complejos', 'Un ensayo sostiene que la lectura crítica es esencial en la era digital, argumentando con ejemplos sobre la desinformación en redes sociales. ¿Qué relación existe entre la tesis y los ejemplos presentados?', '["Los ejemplos no tienen relación con la tesis planteada","Los ejemplos ilustran y respaldan la tesis sobre la importancia de la lectura crítica","Los ejemplos contradicen completamente la tesis","Los ejemplos reemplazan la necesidad de una tesis"]', 1, 'Los ejemplos sobre desinformación sirven para ilustrar y respaldar la tesis planteada sobre la importancia de la lectura crítica.', 'intermedia', 90),
  ('Comprensión de ensayos y textos argumentativos complejos', '¿Cuál de las siguientes estrategias NO ayuda a comprender un ensayo argumentativo complejo?', '["Identificar la tesis central del autor","Reconocer la progresión de los argumentos a lo largo del texto","Leer solo el primer párrafo y asumir el resto del contenido","Distinguir entre los argumentos principales y los ejemplos que los ilustran"]', 2, 'Leer solo el primer párrafo y asumir el resto no permite comprender adecuadamente un ensayo complejo, que requiere seguir la progresión completa del argumento.', 'intermedia', 90),
  ('Comprensión de ensayos y textos argumentativos complejos', 'Un ensayo utiliza una estructura donde primero presenta una tesis, luego una serie de contraargumentos, y finalmente los refuta uno a uno antes de concluir. ¿Qué efecto logra esta estructura en la argumentación?', '["Debilita la tesis al mostrar tantas objeciones","Fortalece la tesis, al mostrar que resiste el análisis de posturas contrarias","Es una estructura incorrecta para un ensayo argumentativo","Elimina la necesidad de presentar evidencia"]', 1, 'Presentar y refutar contraargumentos fortalece la tesis, al demostrar que resiste el análisis de posturas contrarias.', 'avanzada', 120),

  ('Contexto de producción y recepción de una obra', '¿Qué se entiende por "contexto de producción" de una obra literaria?', '["El costo de impresión del libro","Las circunstancias históricas, sociales y culturales en que fue escrita la obra","La cantidad de ejemplares vendidos","El nombre de la editorial que la publicó"]', 1, 'El contexto de producción corresponde a las circunstancias históricas, sociales y culturales en que fue escrita una obra.', 'inicial', 60),
  ('Contexto de producción y recepción de una obra', 'Una obra escrita en tiempos de guerra puede ser interpretada de forma distinta décadas después, en un contexto de paz. ¿A qué concepto corresponde este cambio en la interpretación?', '["Al contexto de producción, únicamente","Al contexto de recepción, que varía según la época del lector","A un error en la traducción de la obra","A que la obra cambia su contenido con el tiempo"]', 1, 'El contexto de recepción se refiere a las circunstancias del lector o época en que la obra es interpretada, y puede variar con el tiempo.', 'intermedia', 90),
  ('Contexto de producción y recepción de una obra', '¿Cuál de las siguientes afirmaciones sobre contexto de producción y recepción es incorrecta?', '["El contexto de producción se refiere a las circunstancias en que se escribió la obra","El contexto de recepción puede variar según la época y el lector","Ambos contextos son siempre exactamente iguales para cualquier obra","Conocer ambos contextos enriquece la interpretación de una obra"]', 2, 'El contexto de producción y el de recepción no son siempre iguales; de hecho, suelen diferir, especialmente cuando la obra se lee mucho después de haber sido escrita.', 'intermedia', 90),
  ('Contexto de producción y recepción de una obra', 'Una novela que en su época fue considerada escandalosa por abordar temas tabú es hoy estudiada como un clásico literario. ¿Qué explica mejor este cambio?', '["La obra cambió su contenido con el paso del tiempo","El contexto de recepción cambió, modificando la valoración social de la obra","La obra perdió calidad literaria con el tiempo","No existe ninguna relación entre la época y la valoración de una obra"]', 1, 'El cambio en la valoración social de una obra a lo largo del tiempo se explica por cambios en el contexto de recepción, no por un cambio en el texto en sí.', 'avanzada', 120),

  ('Perspectiva y sesgos de un texto no literario', '¿Qué se entiende por "sesgo" en un texto no literario?', '["Una inclinación o tendencia que influye en cómo se presenta la información","Un error de ortografía en el texto","La extensión total del texto","El uso de vocabulario técnico"]', 0, 'Un sesgo es una inclinación o tendencia que influye en la forma en que se selecciona y presenta la información en un texto.', 'inicial', 60),
  ('Perspectiva y sesgos de un texto no literario', 'Un artículo sobre un conflicto social solo entrevista a una de las partes involucradas, sin dar espacio a la otra. ¿Qué sesgo se puede identificar en este texto?', '["Ningún sesgo, es una práctica periodística habitual y neutral","Un sesgo de selección de fuentes, al excluir una de las perspectivas relevantes","Un sesgo relacionado únicamente con la extensión del texto","Un sesgo exclusivamente gramatical"]', 1, 'Excluir una de las partes relevantes de un conflicto constituye un sesgo de selección de fuentes, que limita la perspectiva presentada.', 'intermedia', 90),
  ('Perspectiva y sesgos de un texto no literario', '¿Cuál de las siguientes estrategias NO ayuda a identificar la perspectiva o sesgo de un texto no literario?', '["Analizar qué voces o fuentes se incluyen y cuáles se omiten","Identificar el vocabulario valorativo usado para describir a las partes involucradas","Contar el número exacto de palabras que tiene el texto","Comparar el texto con otras fuentes sobre el mismo tema"]', 2, 'Contar el número de palabras no aporta información sobre el sesgo o la perspectiva de un texto, a diferencia de analizar fuentes, vocabulario y comparar con otras versiones.', 'intermedia', 90),
  ('Perspectiva y sesgos de un texto no literario', 'Dos artículos sobre una misma protesta social usan palabras distintas para describir a los manifestantes: uno los llama "ciudadanos organizados" y otro "alborotadores". ¿Qué revela esta diferencia?', '["Que uno de los dos artículos contiene información falsa","Que el uso del lenguaje puede reflejar la perspectiva o sesgo de quien escribe","Que ambos artículos describen hechos completamente distintos","Que el lenguaje no influye en la forma en que se percibe un hecho"]', 1, 'La elección de vocabulario valorativo distinto para describir a los mismos actores revela la perspectiva o sesgo de quien escribe cada texto.', 'avanzada', 120),

  ('Relaciones intertextuales entre obras', '¿Qué se entiende por una "relación intertextual" entre dos obras?', '["Que ambas obras fueron escritas por el mismo autor","Que una obra dialoga, cita o se inspira en elementos de otra obra","Que ambas obras se publicaron el mismo año","Que ambas obras tienen el mismo número de páginas"]', 1, 'Una relación intertextual ocurre cuando una obra dialoga, cita o se inspira en elementos presentes en otra obra.', 'inicial', 60),
  ('Relaciones intertextuales entre obras', 'Una novela contemporánea retoma la estructura del viaje del héroe presente en un relato épico clásico, adaptándola a un contexto actual. ¿Qué tipo de relación se establece entre ambas obras?', '["Ninguna relación, son completamente independientes","Una relación intertextual, al retomar y adaptar elementos de una obra clásica","Una relación de plagio, sin ninguna intención literaria","Una relación que invalida la originalidad de la novela contemporánea"]', 1, 'Retomar y adaptar una estructura narrativa clásica en un contexto nuevo constituye una relación intertextual, un recurso literario legítimo.', 'intermedia', 90),
  ('Relaciones intertextuales entre obras', '¿Cuál de las siguientes NO es una forma de relación intertextual entre obras?', '["Una obra que cita directamente un verso de otra obra","Una obra que parodia la estructura de otra obra reconocida","Dos obras publicadas por editoriales completamente distintas","Una obra que retoma un mito presente en otra tradición literaria"]', 2, 'Que dos obras sean publicadas por editoriales distintas no constituye, por sí solo, una relación intertextual entre ellas.', 'intermedia', 90),
  ('Relaciones intertextuales entre obras', 'Un poema contemporáneo hace referencia a un mito clásico para reflexionar sobre la fragilidad humana actual. ¿Qué función cumple esta relación intertextual en el poema?', '["Ninguna función relevante para la interpretación del poema","Permite establecer un diálogo entre distintas épocas para profundizar un tema universal","Demuestra que el poema no tiene ideas propias","Reduce el valor literario del poema contemporáneo"]', 1, 'La referencia a un mito clásico permite establecer un diálogo entre épocas distintas, profundizando la reflexión sobre un tema universal.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Lectura')
      and name = 'Lectura — 1° Medio'
  )
cross join (select id from public.levels where code = 'regular_1_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: ESCRITURA — 1° MEDIO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Ensayos breves que plantean y defienden una tesis', '¿Cuál es el propósito principal de un ensayo breve?', '["Narrar una historia de ficción con personajes","Plantear y defender una tesis mediante argumentos organizados","Describir un lugar sin ninguna intención argumentativa","Presentar solo datos estadísticos sin interpretación"]', 1, 'Un ensayo breve tiene como propósito plantear y defender una tesis mediante argumentos organizados.', 'inicial', 60),
  ('Ensayos breves que plantean y defienden una tesis', 'Un estudiante redacta un ensayo cuya tesis es que la educación a distancia amplía el acceso a la enseñanza, pero solo entrega un argumento poco desarrollado. ¿Qué debería mejorar?', '["Eliminar la tesis del ensayo","Desarrollar con mayor profundidad el argumento o incorporar argumentos adicionales","Cambiar el ensayo por un texto narrativo","Reducir aún más la extensión del argumento"]', 1, 'Un ensayo persuasivo requiere desarrollar en profundidad sus argumentos o incorporar más de uno para sustentar adecuadamente la tesis.', 'intermedia', 90),
  ('Ensayos breves que plantean y defienden una tesis', '¿Cuál de las siguientes opciones NO corresponde a una buena práctica al escribir un ensayo breve que defiende una tesis?', '["Presentar argumentos relacionados directamente con la tesis","Mantener coherencia entre la tesis planteada y la conclusión","Incluir argumentos que contradicen la propia tesis sin ninguna justificación","Usar ejemplos o evidencia que respalden los argumentos"]', 2, 'Incluir argumentos que contradicen la propia tesis sin justificación debilita la coherencia del ensayo, en vez de fortalecerlo.', 'intermedia', 90),
  ('Ensayos breves que plantean y defienden una tesis', 'En un ensayo, un estudiante plantea la tesis de que el arte callejero embellece las ciudades, pero en la conclusión afirma lo contrario sin explicación. ¿Qué problema presenta este ensayo?', '["Ninguno, es válido cambiar de opinión al final de un ensayo","Una falta de coherencia entre la tesis planteada y la conclusión del ensayo","Un exceso de argumentos bien desarrollados","Un uso excesivo de evidencia"]', 1, 'Contradecir la tesis inicial en la conclusión, sin ninguna justificación argumentativa, rompe la coherencia del ensayo.', 'avanzada', 120),

  ('Textos literarios con distintos recursos y estilos', '¿Qué significa explorar "distintos recursos y estilos" al escribir un texto literario?', '["Escribir siempre exactamente de la misma forma","Experimentar con diferentes formas de narrar, describir o versificar según la intención del texto","Copiar el estilo de un único autor sin ninguna variación","Evitar cualquier tipo de recurso literario"]', 1, 'Explorar distintos recursos y estilos implica experimentar con diferentes formas de narrar o describir, adecuándose a la intención de cada texto.', 'inicial', 60),
  ('Textos literarios con distintos recursos y estilos', 'Un estudiante escribe dos versiones de un mismo relato: una con narrador en primera persona y otra con narrador omnisciente. ¿Qué logra con este ejercicio?', '["Ninguna diferencia relevante entre ambas versiones","Explorar cómo el punto de vista narrativo afecta la percepción del lector sobre la historia","Demostrar que ambas versiones son idénticas","Eliminar por completo la necesidad de un narrador"]', 1, 'Cambiar el punto de vista narrativo permite explorar cómo afecta la percepción del lector sobre la misma historia.', 'intermedia', 90),
  ('Textos literarios con distintos recursos y estilos', '¿Cuál de las siguientes opciones NO corresponde a explorar distintos estilos en la escritura literaria?', '["Probar un tono más poético en una descripción","Cambiar el tipo de narrador según el efecto que se busca lograr","Escribir siempre con las mismas oraciones y estructuras, sin ninguna variación","Variar el ritmo de las oraciones según la emoción que se quiere transmitir"]', 2, 'Mantener siempre las mismas oraciones y estructuras es lo opuesto a explorar distintos estilos, que implica variación intencionada.', 'intermedia', 90),
  ('Textos literarios con distintos recursos y estilos', 'Un estudiante escribe un cuento fantástico usando un estilo minimalista, con oraciones breves y pocos adjetivos, para generar un efecto de extrañeza. ¿Qué relación existe entre el estilo elegido y el efecto buscado?', '["Ninguna relación entre el estilo y el efecto en el lector","El estilo minimalista puede reforzar la sensación de extrañeza al dejar espacios para la interpretación del lector","El estilo minimalista siempre resulta en un texto de mala calidad","El estilo no tiene ninguna influencia en la recepción de un texto fantástico"]', 1, 'Un estilo minimalista, con oraciones breves y pocos adjetivos, puede reforzar un efecto de extrañeza al dejar más espacio a la interpretación del lector.', 'avanzada', 120),

  ('Proceso de escritura recursivo', '¿Qué caracteriza a un proceso de escritura "recursivo"?', '["Que se escribe una sola vez sin volver a revisar el texto","Que las etapas de planificación, escritura y revisión se repiten varias veces, no en un solo orden lineal","Que el texto se repite exactamente igual varias veces","Que solo se revisa la ortografía al final del proceso"]', 1, 'Un proceso de escritura recursivo implica volver varias veces a etapas anteriores (planificar, escribir, revisar), en vez de seguir un único orden lineal.', 'inicial', 60),
  ('Proceso de escritura recursivo', 'Al revisar su segundo borrador, un estudiante decide replantear la tesis inicial de su ensayo y volver a planificar los argumentos. ¿Qué característica del proceso de escritura demuestra esta acción?', '["Que el proceso de escritura es siempre lineal y no admite cambios","Que el proceso de escritura puede ser recursivo, volviendo a etapas anteriores cuando es necesario","Que el estudiante cometió un error al no seguir el proceso correctamente","Que la planificación solo ocurre al inicio del proceso, sin poder repetirse"]', 1, 'Volver a la planificación después de haber avanzado en la escritura es un ejemplo característico del proceso de escritura recursivo.', 'intermedia', 90),
  ('Proceso de escritura recursivo', '¿Cuál de las siguientes situaciones NO refleja un proceso de escritura recursivo?', '["Volver a planificar después de escribir un primer borrador","Revisar y modificar varias veces un mismo párrafo antes de continuar","Escribir el texto una sola vez y entregarlo sin ninguna revisión posterior","Reescribir la introducción luego de definir mejor la conclusión del texto"]', 2, 'Escribir un texto una sola vez sin ninguna revisión posterior es característico de un proceso lineal, no de uno recursivo.', 'intermedia', 90),
  ('Proceso de escritura recursivo', 'Un estudiante, al escribir un ensayo, se da cuenta durante la revisión de que uno de sus argumentos contradice su tesis. Vuelve a la etapa de planificación para ajustar su argumentación. ¿Qué demuestra esta acción sobre el proceso de escritura?', '["Que el proceso de escritura fue un fracaso completo","Que el proceso de escritura recursivo permite corregir inconsistencias detectadas en etapas posteriores","Que la planificación inicial no tiene ninguna importancia","Que revisar un texto nunca aporta cambios relevantes"]', 1, 'El proceso recursivo permite volver a etapas anteriores para corregir inconsistencias detectadas durante la revisión, mejorando el texto final.', 'avanzada', 120),

  ('Convenciones de la lengua escrita', '¿Qué se entiende por "convenciones de la lengua escrita"?', '["Normas de ortografía, puntuación y gramática que rigen la escritura correcta","Reglas que solo se aplican al lenguaje oral","Opiniones personales sobre cómo debería escribirse","Un estilo literario específico de un autor"]', 0, 'Las convenciones de la lengua escrita corresponden a las normas de ortografía, puntuación y gramática que rigen la escritura correcta.', 'inicial', 60),
  ('Convenciones de la lengua escrita', 'Un estudiante revisa su ensayo y corrige el uso de comas, la concordancia verbal y la ortografía de palabras con tilde. ¿Qué aspecto de su escritura está mejorando?', '["El estilo literario del texto","El dominio de las convenciones de la lengua escrita","La extensión del texto","El tema central del ensayo"]', 1, 'Corregir puntuación, concordancia y ortografía corresponde a mejorar el dominio de las convenciones de la lengua escrita.', 'intermedia', 90),
  ('Convenciones de la lengua escrita', '¿Cuál de las siguientes opciones NO corresponde a una convención de la lengua escrita?', '["El uso correcto de la tilde según las reglas de acentuación","La concordancia entre sujeto y verbo","La preferencia personal de un lector por cierto género literario","El uso adecuado de los signos de puntuación"]', 2, 'La preferencia de un lector por un género literario es una cuestión de gusto, no una convención normativa de la lengua escrita.', 'intermedia', 90),
  ('Convenciones de la lengua escrita', 'Un estudiante domina un vocabulario amplio y escribe ideas complejas, pero comete errores frecuentes de puntuación que dificultan la comprensión del texto. ¿Qué debería priorizar al revisar su escritura?', '["Ignorar los errores de puntuación, ya que el vocabulario es más importante","Corregir los errores de puntuación para asegurar la claridad y comprensión del texto","Reducir el vocabulario utilizado en el texto","Eliminar las ideas complejas del texto"]', 1, 'Corregir los errores de puntuación es prioritario cuando dificultan la comprensión del texto, independientemente de la riqueza del vocabulario o de las ideas.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Escritura')
      and name = 'Escritura — 1° Medio'
  )
cross join (select id from public.levels where code = 'regular_1_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: COMUNICACIÓN ORAL — 1° MEDIO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Disertaciones orales con rigor argumentativo', '¿Qué caracteriza a una disertación oral con rigor argumentativo?', '["Presentar opiniones sin ninguna evidencia que las respalde","Presentar una tesis sustentada con argumentos organizados y evidencia pertinente","Improvisar el contenido sin ninguna planificación previa","Repetir la opinión de otra persona sin ningún análisis propio"]', 1, 'Una disertación con rigor argumentativo sustenta su tesis con argumentos organizados y evidencia pertinente.', 'inicial', 60),
  ('Disertaciones orales con rigor argumentativo', 'Un estudiante presenta una disertación sobre el uso de energías renovables, incluyendo datos de estudios y ejemplos de países que las han implementado. ¿Qué logra con esta estrategia?', '["Confundir a la audiencia con demasiada información","Fortalecer el rigor argumentativo de su disertación mediante evidencia concreta","Eliminar la necesidad de tener una tesis clara","Hacer la disertación menos creíble"]', 1, 'Incorporar datos y ejemplos concretos fortalece el rigor argumentativo de una disertación oral.', 'intermedia', 90),
  ('Disertaciones orales con rigor argumentativo', '¿Cuál de las siguientes prácticas NO corresponde a una disertación oral con rigor argumentativo?', '["Organizar los argumentos de manera lógica y progresiva","Presentar evidencia que respalde cada argumento","Basar toda la disertación en una opinión personal sin ninguna evidencia","Anticiparse a posibles objeciones y responderlas"]', 2, 'Basar toda una disertación solo en una opinión personal, sin evidencia, contradice el rigor argumentativo esperado.', 'intermedia', 90),
  ('Disertaciones orales con rigor argumentativo', 'Durante una disertación, un estudiante presenta un argumento sólido, pero cuando se le pregunta por la fuente de sus datos, no puede identificarla con precisión. ¿Qué debilidad revela esta situación?', '["Ninguna, no es necesario identificar las fuentes en una disertación oral","Una debilidad en el rigor argumentativo, al no poder respaldar con precisión la evidencia presentada","Que el argumento es completamente inválido","Que la disertación no necesitaba ninguna evidencia"]', 1, 'No poder identificar con precisión la fuente de los datos presentados revela una debilidad en el respaldo y rigor de la argumentación.', 'avanzada', 120),

  ('Debates sobre temas contingentes', '¿Qué se entiende por un "tema contingente" en el contexto de un debate?', '["Un tema de actualidad, relevante para la sociedad en el presente","Un tema exclusivamente histórico sin ninguna relación con la actualidad","Un tema ficticio inventado para el debate","Un tema que no genera ninguna opinión dividida"]', 0, 'Un tema contingente es un tema de actualidad, relevante para la sociedad en el presente, que suele generar distintas posturas.', 'inicial', 60),
  ('Debates sobre temas contingentes', 'En un debate sobre el uso de energías renovables en Chile, los participantes citan datos actuales sobre políticas energéticas del país. ¿Por qué este es un ejemplo de tema contingente?', '["Porque no tiene relación con la realidad actual","Porque aborda una problemática actual y relevante para la sociedad","Porque es un tema exclusivamente teórico sin aplicación real","Porque no genera ninguna opinión dividida entre los participantes"]', 1, 'Un tema contingente aborda una problemática actual y relevante para la sociedad, como el uso de energías renovables.', 'intermedia', 90),
  ('Debates sobre temas contingentes', '¿Cuál de las siguientes actitudes NO es adecuada al debatir sobre un tema contingente?', '["Informarse previamente sobre el tema antes del debate","Considerar distintas posturas antes de formar una opinión","Mantener una postura sin escuchar ni considerar ningún argumento contrario","Fundamentar la propia postura con datos actualizados"]', 2, 'Mantener una postura sin escuchar argumentos contrarios contradice la actitud de apertura y análisis crítico esperada en un debate.', 'intermedia', 90),
  ('Debates sobre temas contingentes', 'En un debate sobre un tema contingente y polémico, dos participantes presentan datos actualizados pero interpretados de forma distinta. ¿Qué se puede concluir de esta situación?', '["Uno de los dos participantes necesariamente está mintiendo","Un mismo dato puede interpretarse de forma distinta según la perspectiva del participante","Los datos actualizados no tienen ningún valor en un debate","El debate no cumplió ningún propósito por existir desacuerdo"]', 1, 'Un mismo dato puede admitir interpretaciones distintas según la perspectiva de quien lo analiza, sin que ello implique falsedad.', 'avanzada', 120),

  ('Análisis crítico del discurso público', '¿Qué implica realizar un análisis crítico del discurso público (por ejemplo, político)?', '["Aceptar sin cuestionamiento todo lo que dice la autoridad","Examinar las intenciones, argumentos y recursos persuasivos usados en el discurso","Memorizar el discurso completo sin ningún análisis","Evaluar solamente la duración del discurso"]', 1, 'El análisis crítico del discurso público implica examinar las intenciones, argumentos y recursos persuasivos utilizados.', 'inicial', 60),
  ('Análisis crítico del discurso público', 'Un discurso político utiliza reiteradamente la frase "el pueblo unido" sin presentar propuestas concretas. ¿Qué debilidad se puede identificar desde un análisis crítico?', '["Ninguna, la repetición de frases es siempre una estrategia argumentativa sólida","La ausencia de propuestas concretas detrás de un discurso emotivo o genérico","Que el discurso es completamente objetivo y verificable","Que la frase utilizada garantiza la validez del discurso"]', 1, 'Un discurso que apela solo a frases emotivas genéricas, sin propuestas concretas, presenta una debilidad argumentativa identificable con un análisis crítico.', 'intermedia', 90),
  ('Análisis crítico del discurso público', '¿Cuál de las siguientes estrategias NO corresponde a un análisis crítico del discurso público?', '["Identificar la intención comunicativa del discurso","Analizar los recursos persuasivos utilizados","Aceptar el discurso solo por la popularidad de quien lo pronuncia","Contrastar las afirmaciones del discurso con datos verificables"]', 2, 'Aceptar un discurso solo por la popularidad de quien lo pronuncia contradice el análisis crítico, que exige examinar el contenido, no la fama del emisor.', 'intermedia', 90),
  ('Análisis crítico del discurso público', 'Un discurso público usa cifras económicas sin citar su fuente y las presenta como hechos indiscutibles. ¿Qué debería hacer un analista crítico frente a esta situación?', '["Aceptar las cifras sin cuestionar su origen","Verificar la fuente de las cifras antes de aceptarlas como válidas","Ignorar por completo el discurso sin ningún análisis","Asumir que todas las cifras públicas son siempre verdaderas"]', 1, 'Un analista crítico debe verificar la fuente de las cifras presentadas antes de aceptarlas como válidas, en vez de asumirlas sin cuestionamiento.', 'avanzada', 120),

  ('Estrategias de persuasión oral de manera ética', '¿Qué caracteriza a una estrategia de persuasión oral ética?', '["Utilizar información falsa si esto ayuda a convencer a la audiencia","Convencer a la audiencia basándose en argumentos válidos y evidencia verificable","Manipular las emociones del público sin ninguna base argumentativa","Ignorar por completo los argumentos contrarios sin ninguna consideración"]', 1, 'La persuasión ética se basa en argumentos válidos y evidencia verificable, no en información falsa o manipulación.', 'inicial', 60),
  ('Estrategias de persuasión oral de manera ética', 'Un estudiante, al preparar un discurso persuasivo, decide no exagerar ni inventar datos, y en su lugar cita fuentes reales para respaldar sus argumentos. ¿Qué principio ético está aplicando?', '["Ninguno, esta práctica no tiene relación con la ética","La honestidad y el respaldo verificable de la información presentada","Una estrategia que debilita innecesariamente su discurso","Una práctica que solo dificulta la persuasión"]', 1, 'Citar fuentes reales sin exagerar ni inventar datos refleja el principio ético de honestidad y respaldo verificable de la información.', 'intermedia', 90),
  ('Estrategias de persuasión oral de manera ética', '¿Cuál de las siguientes estrategias NO corresponde a una persuasión oral ética?', '["Presentar evidencia verificable para respaldar los argumentos","Apelar a las emociones del público de forma honesta y relacionada con el tema","Manipular al público mediante datos falsos o exagerados","Reconocer los límites o matices del propio argumento"]', 2, 'Manipular al público con datos falsos o exagerados contradice los principios de una persuasión oral ética.', 'intermedia', 90),
  ('Estrategias de persuasión oral de manera ética', 'Un estudiante logra convencer a su audiencia exagerando las consecuencias negativas de un problema, sin que esas consecuencias estén respaldadas por evidencia real. ¿Qué problema ético presenta esta estrategia?', '["Ninguno, si logra convencer a la audiencia el fin justifica los medios","Manipula a la audiencia mediante información no verificada, lo que compromete la ética de la persuasión","Es una estrategia recomendable en cualquier discurso persuasivo","La exageración siempre es una herramienta válida y ética"]', 1, 'Exagerar consecuencias sin respaldo real constituye una manipulación de la audiencia, que compromete la ética de la persuasión.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Comunicación Oral')
      and name = 'Comunicación Oral — 1° Medio'
  )
cross join (select id from public.levels where code = 'regular_1_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );

-- ============================================================================
-- EJE: INVESTIGACIÓN — 1° MEDIO (4 objetivos x 4 preguntas = 16)
-- ============================================================================
insert into public.questions (
  subject_id, level_id, lesson_id, prompt, choices, correct_index, explanation,
  learning_objective_id, difficulty, question_type, points, estimated_seconds,
  review_status, validation_status, is_active, source_type, generated_by, generated_at
)
select
  (select id from public.subjects where name = 'Lengua Castellana y Comunicación'),
  lv.id, null, v.prompt, v.choices::jsonb, v.correct_index, v.explanation,
  lo.id, v.difficulty, 'seleccion_multiple', 1, v.estimated_seconds,
  'borrador', 'ai_generated_review_required', true, 'validapp_original',
  'claude-sonnet-5 (validapp-assessments)', now()
from (values
  ('Proyecto de investigación con objetivos y metodología', '¿Qué elementos debe incluir un proyecto de investigación antes de comenzar a recopilar información?', '["Solo el título del tema a investigar","Los objetivos de la investigación y una metodología para alcanzarlos","Únicamente las conclusiones esperadas","Solo un listado de fuentes sin ningún objetivo definido"]', 1, 'Antes de recopilar información, un proyecto de investigación debe definir sus objetivos y la metodología para alcanzarlos.', 'inicial', 60),
  ('Proyecto de investigación con objetivos y metodología', 'Un estudiante define como objetivo de su investigación "identificar las causas de la deserción escolar en su comuna" y planifica encuestas y revisión de estudios previos como metodología. ¿Qué relación existe entre el objetivo y la metodología?', '["Ninguna relación entre ambos elementos","La metodología define cómo se alcanzará el objetivo planteado","El objetivo depende exclusivamente de la metodología, sin ninguna relación lógica","La metodología reemplaza la necesidad de un objetivo"]', 1, 'La metodología (encuestas, revisión de estudios) define cómo se alcanzará el objetivo planteado en la investigación.', 'intermedia', 90),
  ('Proyecto de investigación con objetivos y metodología', '¿Cuál de las siguientes acciones NO corresponde a diseñar un proyecto de investigación con objetivos y metodología?', '["Definir con claridad qué se busca lograr con la investigación","Planificar qué instrumentos o fuentes se usarán para recopilar información","Comenzar a redactar las conclusiones antes de recopilar cualquier información","Establecer un cronograma o etapas para desarrollar la investigación"]', 2, 'Redactar conclusiones antes de recopilar información contradice el proceso lógico de una investigación, que exige primero definir objetivos y metodología.', 'intermedia', 90),
  ('Proyecto de investigación con objetivos y metodología', 'Un estudiante plantea el objetivo "investigar todo sobre el cambio climático" sin definir ninguna metodología específica. ¿Qué problema presenta este proyecto de investigación?', '["Ninguno, el objetivo es suficientemente claro y manejable","El objetivo es demasiado amplio y falta una metodología concreta para abordarlo","La metodología no es necesaria si el tema es interesante","El objetivo no tiene ninguna relación con el cambio climático"]', 1, 'Un objetivo tan amplio, sin metodología definida, dificulta el desarrollo manejable de una investigación.', 'avanzada', 120),

  ('Confiabilidad de fuentes digitales', '¿Qué criterio es más relevante para evaluar la confiabilidad de una fuente digital?', '["La cantidad de anuncios publicitarios que tiene el sitio","La identificación del autor, la institución y la posibilidad de verificar la información","El diseño gráfico y los colores del sitio web","La cantidad de veces que aparece en los resultados de búsqueda"]', 1, 'La confiabilidad de una fuente digital depende de la identificación del autor o institución y de la posibilidad de verificar la información, no de aspectos visuales o de posicionamiento en buscadores.', 'inicial', 60),
  ('Confiabilidad de fuentes digitales', 'Un estudiante encuentra un artículo sin autor identificado que presenta afirmaciones sin ninguna fuente ni dato verificable. ¿Qué debería concluir sobre esta fuente?', '["Que es una fuente completamente confiable por estar publicada en internet","Que su confiabilidad es cuestionable y debería contrastarse con otras fuentes","Que toda la información en internet es igualmente confiable","Que no es necesario verificar ninguna fuente digital"]', 1, 'Una fuente sin autor identificado ni respaldo verificable tiene confiabilidad cuestionable y debería contrastarse con otras fuentes.', 'intermedia', 90),
  ('Confiabilidad de fuentes digitales', '¿Cuál de los siguientes criterios NO es relevante para evaluar la confiabilidad de una fuente digital?', '["La fecha de publicación o última actualización","Si la institución o autor tiene reconocimiento en el área","La cantidad de colores utilizados en el diseño del sitio","Si la información puede contrastarse con otras fuentes confiables"]', 2, 'El diseño gráfico no es relevante para evaluar la confiabilidad de una fuente, a diferencia de la fecha, la autoría y la posibilidad de contrastar la información.', 'intermedia', 90),
  ('Confiabilidad de fuentes digitales', 'Un estudiante encuentra información contradictoria entre un sitio institucional reconocido y un blog personal sin fuentes citadas. ¿Qué decisión sería más adecuada?', '["Confiar más en el blog personal, ya que tiene un lenguaje más cercano","Dar mayor validez a la fuente institucional reconocida, que cita respaldo verificable","Ignorar ambas fuentes sin ningún análisis adicional","Elegir aleatoriamente cuál información usar"]', 1, 'Ante una contradicción, es razonable dar mayor validez a la fuente institucional reconocida, que ofrece respaldo verificable.', 'avanzada', 120),

  ('Síntesis de múltiples fuentes en un texto propio', '¿Qué significa sintetizar información de múltiples fuentes en un texto propio?', '["Copiar textualmente cada una de las fuentes consultadas","Integrar y reformular con palabras propias las ideas principales de varias fuentes","Usar solo la fuente más extensa e ignorar las demás","Enumerar las fuentes sin ningún desarrollo del contenido"]', 1, 'Sintetizar implica integrar y reformular con palabras propias las ideas principales de varias fuentes consultadas.', 'inicial', 60),
  ('Síntesis de múltiples fuentes en un texto propio', 'Un estudiante consulta cinco fuentes distintas sobre un tema y redacta un texto propio que integra las ideas principales de todas ellas, citando cada una. ¿Qué habilidad está demostrando?', '["Una copia literal de las fuentes consultadas","La capacidad de sintetizar información de múltiples fuentes en un texto coherente","Una investigación superficial sin ningún análisis","El uso de una sola fuente disfrazada de varias"]', 1, 'Integrar las ideas principales de varias fuentes en un texto coherente y citado demuestra la capacidad de síntesis.', 'intermedia', 90),
  ('Síntesis de múltiples fuentes en un texto propio', '¿Cuál de las siguientes acciones NO corresponde a una síntesis adecuada de múltiples fuentes?', '["Identificar ideas comunes y divergentes entre las fuentes consultadas","Reformular las ideas principales con palabras propias","Copiar y pegar fragmentos completos de cada fuente sin ninguna reformulación","Organizar la información integrada en un texto coherente"]', 2, 'Copiar y pegar fragmentos sin reformulación no constituye una síntesis, sino una recopilación literal de textos ajenos.', 'intermedia', 90),
  ('Síntesis de múltiples fuentes en un texto propio', 'Al sintetizar información de varias fuentes que presentan datos contradictorios sobre un mismo tema, ¿qué estrategia es más adecuada para un texto propio?', '["Elegir una sola fuente e ignorar las demás sin ninguna justificación","Presentar los distintos datos, explicando las posibles razones de la contradicción","Omitir cualquier mención a la contradicción encontrada","Inventar un dato propio para resolver la contradicción"]', 1, 'Presentar los distintos datos y explicar las posibles razones de la contradicción es una estrategia más honesta y completa que ignorarla o inventar información.', 'avanzada', 120),

  ('Presentación de resultados en distintos formatos', '¿Por qué puede ser útil presentar los resultados de una investigación en distintos formatos (escrito, oral, multimedial)?', '["Porque siempre es obligatorio usar los tres formatos a la vez","Porque cada formato permite comunicar la información de forma adecuada según el contexto y la audiencia","Porque un solo formato nunca es válido para comunicar resultados","Porque los formatos multimediales reemplazan la necesidad de contenido"]', 1, 'Cada formato tiene ventajas distintas según el contexto y la audiencia a la que se dirige la presentación de resultados.', 'inicial', 60),
  ('Presentación de resultados en distintos formatos', 'Un estudiante decide presentar los resultados de su investigación mediante una infografía para una exposición breve frente al curso, en vez de un informe extenso. ¿Qué justifica esta decisión?', '["Ninguna razón válida, siempre se debe usar un informe extenso","La infografía permite comunicar de forma visual y sintética la información en un formato breve","La infografía elimina la necesidad de tener resultados reales","Los formatos visuales no son adecuados para comunicar investigaciones"]', 1, 'Una infografía permite comunicar de forma visual y sintética los resultados, adecuada para una exposición breve frente al curso.', 'intermedia', 90),
  ('Presentación de resultados en distintos formatos', '¿Cuál de las siguientes opciones NO es un formato adecuado para presentar los resultados de una investigación?', '["Un informe escrito con conclusiones fundamentadas","Una presentación oral con apoyo visual","Una conversación informal sin ningún contenido de la investigación","Un video breve que resuma los hallazgos principales"]', 2, 'Una conversación informal sin contenido de la investigación no cumple la función de comunicar resultados, a diferencia de un informe, una presentación o un video.', 'intermedia', 90),
  ('Presentación de resultados en distintos formatos', 'Un estudiante debe comunicar los resultados de su investigación tanto a su curso como a la comunidad escolar en general. ¿Qué estrategia sería más adecuada?', '["Usar exactamente el mismo formato y nivel de detalle para ambas audiencias","Adaptar el formato y la profundidad de la información según cada audiencia y contexto","Presentar los resultados únicamente de forma oral, sin ningún apoyo visual","Omitir la presentación a la comunidad escolar por ser una audiencia distinta"]', 1, 'Adaptar el formato y la profundidad de la información según cada audiencia permite comunicar los resultados de forma más efectiva en ambos contextos.', 'avanzada', 120)
) as v(short_name, prompt, choices, correct_index, explanation, difficulty, estimated_seconds)
join public.learning_objectives lo
  on lo.short_name = v.short_name
  and lo.unit_id = (
    select id from public.units
    where strand_id = (select id from public.strands where subject_id = (select id from public.subjects where name = 'Lengua Castellana y Comunicación') and name = 'Investigación')
      and name = 'Investigación — 1° Medio'
  )
cross join (select id from public.levels where code = 'regular_1_medio') as lv
where lo.level_id = lv.id
  and not exists (
    select 1 from public.questions q2
    where q2.learning_objective_id = lo.id and q2.prompt = v.prompt
  );
